import React, { useState, useEffect } from 'react';
import './AppMain.css'
import { User, Download, Calendar, ClipboardPenLine, Plus, ArrowLeft } from 'lucide-react';
import { useLocation, useNavigate } from 'react-router-dom';
import axios from 'axios'

function AppMain() {
  const location = useLocation();
  const navigate = useNavigate();
  const username = location.state?.username || "Admin";
  const [showMenu, setShowMenu] = useState(false);
  const [historial, setHistorial] = useState([]);
  const [active, setActive] = useState("registro");

  // Select de los nuevos registros
  const [proyects, setProyects] = useState([]);
  const [task, setTask] = useState([]);

  useEffect(() => {
    axios.get('http://localhost:8081/api/history/proyect', {
      auth: {
        username: 'ventu',
        password: '123'
      }
    }).then(res => {
      setProyects(res.data);
    }).catch(err => {
      console.error("Los proyectos no se han cargado:", err);
    })

    axios.get('http://localhost:8081/api/history/task', {
      auth: {
        username: 'ventu',
        password: '123'
      }
    }).then(res => {
      const uniqueTask = Array.from(new Map(res.data.map(t => [t.task, t])).values());
      setTask(uniqueTask);
    }).catch(err => {
      console.log("Las tareas no se han cargado:", err);
    })
  }, [])

  // Nuevo Registro
  const [showForm, setShowForm] = useState(false);
  const [formData, setFormData] = useState({
    username: username,
    proyect: '',
    task: '',
    hours: '',
    description: ''
  });

  const [formProyect, setFormProyect] = useState({
    proyect: '',
    description: ''
  });

  const [formTask, setFormTask] = useState({
    task: ''
  })

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    axios.post('http://localhost:8081/api/history/create/history', formData, {
      auth: {
        username: 'ventu',
        password: '123'
      }
    }).then(res => {
      alert(res.data);
      setShowForm(false);
      window.location.reload();
    }).catch(err => {
      console.error("Error al guardar el historial", err);
    })
  }

  const handleChangeProyect = (e) => {
    const { name, value } = e.target;
    setFormProyect({ ...formProyect, [name]: value });
  };

  const handleSubmitProyect = (e) => {
    e.preventDefault();
    axios.post('', formProyect, {
      auth: {
        username: 'ventu',
        password: '123'
      }
    }).then(res => {
      alert(res.data);
      setShowForm(false);
      window.location.reload();
    }).catch(err => {
      console.error("Error al guardar proyecto", err);
    })
  }

  const handleChangeTask = (e) => {
    const { name, value } = e.target;
    setFormTask({ ...formTask, [name]: value});
  };

  const handleSubmitTask = (e) => {
    e.preventDefault();
    axios.post('', formTask, {
      auth: {
        username: 'ventu',
        password: '123'
      }
    }).then(res => {
      alert(res.data);
      setShowForm(false);
      window.location.reload();
    }).catch(err => {
      console.error("Error al guardad tarea", err);
    })
  }

  // Cargar los datos al cargar la página
  useEffect(() => {
    axios.get('http://localhost:8081/api/history', {
      auth: {
        username: 'ventu',
        password: '123'
      }
    })
      .then(res => {
        setHistorial(res.data);
      })
      .catch(err => {
        console.error("Error al obtener historial:", err);
      });
  }, []);

  const toggleMenu = () => {
    setShowMenu(!showMenu);
  };

  const logout = () => {
    navigate("/");
  };

  return (
    <div className='Main'>
      <header className='Main-header'>
        <img src="/logoQuiros.png" />
        <div className='usuario' onClick={toggleMenu}>
          <User />
          <strong>{username}</strong>
        </div>
        {showMenu && (
          <div className='dropdown'>
            <button onClick={logout}>Cerrar Sesion</button>
          </div>
        )}
      </header>
      <main>
        <div className='Main-menu'>
          <button className={active === "registro" ? "active" : ""} onClick={() => setActive("registro")}><Calendar />Registro Horas</button>
          <button className={active === "reportes" ? "active" : ""} onClick={() => setActive("reportes")}><ClipboardPenLine />Reportes</button>
        </div>
        <div className='Main-body'>
          {active === "registro" && (
            <>
              <button onClick={() => setShowForm(true)}><Plus />Añadir registro</button>
              <button onClick={() => setActive("proyectos")}><Plus />Ver Proyectos</button>
              <button onClick={() => setActive("tareas")}><Plus />Ver Tareas</button>
              {showForm && (
                <div className='modal-overlay'>
                  <div className='modal'>
                    <h2>Nuevo Registro de Horas</h2>
                    <form onSubmit={handleSubmit}>
                      <select name='proyect' placeholder='Proyecto' value={formData.proyect} onChange={handleChange} required>
                        <option value="">Seleccion un proyecto</option>
                        {proyects.map((proyec) => (
                          <option key={proyec.id} value={proyec.proyect}>{proyec.proyect}</option>
                        ))}
                      </select>
                      <select name='task' placeholder='Tarea' value={formData.task} onChange={handleChange} required>
                        <option value="">Selecciona una tarea</option>
                        {task.map((tasks) => (
                          <option key={tasks.id} value={tasks.task}>{tasks.task}</option>
                        ))}
                      </select>
                      <input name='hours' placeholder='Horas' value={formData.hours} onChange={handleChange} required />
                      <textarea name='description' placeholder='Descripcion' value={formData.description} onChange={handleChange} required />
                      <button type='submit'>Guardar</button>
                      <button type='button' onClick={() => setShowForm(false)}>Cancelar</button>
                    </form>
                  </div>
                </div>
              )}
              <table className='table'>
                <thead>
                  <tr>
                    <td>Usuario</td>
                    <td>Proyecto</td>
                    <td>Tarea</td>
                    <td>Horas</td>
                    <td>Descripcion</td>
                  </tr>
                </thead>
                <tbody>
                  {[...historial].reverse().map((item, index) => (
                    <tr key={index}>
                      <td>{item.user}</td>
                      <td>{item.proyect}</td>
                      <td>{item.task}</td>
                      <td>{item.hours}</td>
                      <td>{item.description}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </>
          )}

          {active === "proyectos" && (
            <>
              <button onClick={() => setActive("registro")}><ArrowLeft /> Volver</button>
              <button onClick={() => setShowForm(true)}><Plus />Añadir Proyecto</button>
              {showForm && (
                <div className='modal-overlay'>
                  <div className='modal'>
                    <h2>Nuevo Proyecto</h2>
                    <form onSubmit={handleSubmitProyect}>
                      <input name='proyect' placeholder='Proyecto' value={formProyect.proyect} onChange={handleChangeProyect} required />
                      <input name='description' placeholder='Descripcion' value={formProyect.description} onChange={handleChangeProyect} required />
                      <button type='submit'>Guardar</button>
                      <button type='button' onClick={() => setShowForm(false)}>Cancelar</button>
                    </form>
                  </div>
                </div>
              )}
              <table className='table'>
                <thead>
                  <tr>
                    <td>Proyecto</td>
                    <td>Descripcion</td>
                  </tr>
                </thead>
                <tbody>
                  {proyects.map((proyec, index) => (
                    <tr key={index}>
                      <td>{proyec.proyect}</td>
                      <td>{proyec.description}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </>
          )}

          {active === "tareas" && (
            <>
              <button onClick={() => setActive("registro")}><ArrowLeft /> Volver</button>
              <button onClick={() => setShowForm(true)}><Plus />Añadir Tarea</button>
              {showForm && (
                <div className='modal-overlay'>
                  <div className='modal'>
                    <h2>Nueva Tarea</h2>
                    <form>
                      <input name="task" placeholder='Tarea' value={formTask.task} onChange={handleChangeTask} required />
                      <button type='submit'>Guardar</button>
                      <button type='button' onClick={() => setShowForm(false)}>Cancelar</button>
                    </form>
                  </div>
                </div>
              )}
              <table className='table'>
                <thead>
                  <td>Tarea</td>
                </thead>
                <tbody>
                  {task.map((tarea, index) => (
                    <tr key={index}>
                      <td>{tarea.task}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </>
          )}
        </div>
      </main>
    </div>
  );
}

export default AppMain;
